-- =====================================================================
-- V14: CONTRACT rate cards for Amazon Shipping, Ekart, Pikndel, XpressBees B2B,
-- and switch these partners (plus TCI) off their V8 SAMPLE data.
-- GENERATED by data/generators/gen_contract_cards.py - do not edit by hand.
--
-- GST is NOT in these rates: MarginTaxPolicy adds margin + 18% GST on top
-- (all four documents say GST extra / exclusive, except Amazon - see below).
-- Assumptions are marked ASSUMPTION; confirm each with the partner.
-- =====================================================================

-- 1. Sample data off for partners moving to real data. Rows are kept for history.
UPDATE SO_RATE_SERVICE SET ENABLED = FALSE WHERE PARTNER_ID IN (4, 9, 10, 11, 14);
UPDATE SO_RATE_CARD
SET STATUS = 'RETIRED', EFFECTIVE_TO = DATE '2026-10-16', UPDATED_AT = CURRENT_TIMESTAMP
WHERE DATA_STATUS = 'SAMPLE'
  AND SERVICE_ID IN (SELECT ID FROM SO_RATE_SERVICE WHERE PARTNER_ID IN (4, 9, 10, 11, 14));
-- Sample zone rows would override the V12 rules (exact-pincode rows win) with zone keys
-- (A/B/C/E) that the real cards don't have.
DELETE FROM SO_ZONE_MAP WHERE PARTNER_ID IN (4, 9, 10, 11, 14);
-- TCI (9): real zone rules (V12) and pincodes (V13) are loaded, but no card: its annexure has
-- 500 g rates AND 5 kg / 10 kg slab rates without saying which applies from what weight. Ask TCI.

-- 2. Services
INSERT INTO SO_RATE_SERVICE (PARTNER_ID, SERVICE_CODE, SERVICE_NAME, PRICING_MODEL, MODE, ENABLED)
VALUES (4, 'STANDARD', 'Amazon Shipping Standard', 'ZONE_SLAB', 'SURFACE', TRUE),
       (4, 'EXPRESS', 'Amazon Shipping Express', 'ZONE_SLAB', 'AIR', TRUE),
       (10, 'FLAT_2KG', 'Ekart Flat (2 kg + per kg)', 'ZONE_SLAB', 'SURFACE', TRUE),
       (11, 'NDD', 'Pikndel Next Day Delivery', 'ZONE_SLAB', 'SURFACE_AIR', TRUE),
       (14, 'B2B_SURFACE', 'XpressBees B2B Surface', 'B2B_FREIGHT', 'SURFACE', TRUE);


-- ---------------------------------------------------------------------
-- Amazon Shipping (4). Source: SHIP-ORBIT_8998775448_2026-10-08.xlsx
-- Slab per 0.5 kg row, exactly as the card (prices step 0.5 kg up to 5 kg, 1 kg after,
-- so a first + additional formula would be wrong). Zones from V12. DIM divisor 5000, COD fee Rs 30.
-- ASSUMPTION: rates exclude GST (card is silent; GST added by the engine).
-- ASSUMPTION: Standard max 60.5 kg. From 61 kg every zone is Rs 1,999 (2x the 60.5 kg Local rate,
--             Local = Remote) - treated as 'not offered' until Amazon confirms.
-- ASSUMPTION: Express flat from 62 kg loaded as is (looks like a cap) - confirm.
-- ASSUMPTION: COD Rs 30 flat (card gives no %). RTO = 100% of forward (card is silent).
-- Reverse leg sheets loaded as REVERSE slabs (identical to forward today).
-- ---------------------------------------------------------------------
