SELECT (SELECT c.ID FROM SO_RATE_CARD c WHERE c.SERVICE_ID = (SELECT s.ID FROM SO_RATE_SERVICE s WHERE s.PARTNER_ID = 4 AND s.SERVICE_CODE = 'STANDARD') AND c.VERSION_LABEL = 'AMZ-2026-10-08'), v.CODE, v.SEQ, v.CALC, CAST(v.RATE AS NUMERIC), CAST(v.FIXED AS NUMERIC), CAST(v.MN AS NUMERIC), CAST(v.MX AS NUMERIC), v.BASE, CAST(v.BC AS VARCHAR), CAST(v.TF AS NUMERIC), CAST(v.TT AS NUMERIC), v.AP, v.DIRS
FROM (VALUES ('COD', 40, 'FLAT', 0, 30, NULL, NULL, 'NONE', NULL, NULL, NULL, 'COD', 'FORWARD')) AS v(CODE, SEQ, CALC, RATE, FIXED, MN, MX, BASE, BC, TF, TT, AP, DIRS);
