-- ---------------------------------------------------------------------
-- Ekart (10). Source: Ekart/rates.docx
-- Rs 90 up to 2 kg anywhere in India + Rs 35 per additional kg. RTO Rs 0, COD Rs 0, GST 18% extra.
-- Chargeable = max(dead, L*B*H/5000). One zone: ALL (V12).
-- ASSUMPTION: max weight 50 kg (card gives none). EFFECTIVE_FROM = load date (card gives none).
-- Insurance clause (Rs 2,000 or 50% of invoice) is Ekart's liability limit, not a charge.
-- ---------------------------------------------------------------------
INSERT INTO SO_RATE_CARD (SERVICE_ID, VERSION_LABEL, STATUS, DATA_STATUS, EFFECTIVE_FROM, EFFECTIVE_TO, VOLUMETRIC_DIVISOR, CFT_KG, MIN_CHARGEABLE_WEIGHT_KG, MAX_WEIGHT_KG, MAX_DISTANCE_KM, MPS_RULE, RTO_RULE, RTO_PERCENT, MIN_BILL, RATES_INCLUDE_GST, ROUNDING)
