-- ODA: Rs 3/kg, min Rs 800 (ODA-1 rate)
-- STATE_SURCHARGE: Rs 2/kg into Kerala, J&K
-- FUEL_SURCHARGE: 25% of basic freight
-- FOV: Rs 100 per waybill
-- WAYBILL: Rs 100 per waybill
INSERT INTO SO_RATE_CHARGE_RULE (RATE_CARD_ID, CHARGE_CODE, SEQ, CALC_TYPE, RATE_VALUE, FIXED_AMOUNT, MIN_AMOUNT, MAX_AMOUNT, BASE, BASE_CODES, TIER_FROM, TIER_TO, APPLIES_WHEN, DIRECTIONS)
SELECT (SELECT c.ID FROM SO_RATE_CARD c WHERE c.SERVICE_ID = (SELECT s.ID FROM SO_RATE_SERVICE s WHERE s.PARTNER_ID = 14 AND s.SERVICE_CODE = 'B2B_SURFACE') AND c.VERSION_LABEL = 'XB-B2B-2026-10'), v.CODE, v.SEQ, v.CALC, CAST(v.RATE AS NUMERIC), CAST(v.FIXED AS NUMERIC), CAST(v.MN AS NUMERIC), CAST(v.MX AS NUMERIC), v.BASE, CAST(v.BC AS VARCHAR), CAST(v.TF AS NUMERIC), CAST(v.TT AS NUMERIC), v.AP, v.DIRS
FROM (VALUES ('ODA', 10, 'PER_UNIT', 3, 0, 800, NULL, 'NONE', NULL, NULL, NULL, 'ODA_DESTINATION', 'FORWARD,RTO'),
       ('STATE_SURCHARGE', 20, 'PER_UNIT', 2, 0, NULL, NULL, 'NONE', NULL, NULL, NULL, 'SPECIAL_CITY', 'FORWARD'),
       ('FUEL_SURCHARGE', 30, 'PERCENT', 25, 0, NULL, NULL, 'CHARGE_CODES', 'BASE', NULL, NULL, 'ALWAYS', 'FORWARD,RTO,REVERSE'),
       ('FOV', 50, 'FLAT', 0, 100, NULL, NULL, 'NONE', NULL, NULL, NULL, 'ALWAYS', 'FORWARD'),
       ('WAYBILL', 60, 'FLAT', 0, 100, NULL, NULL, 'NONE', NULL, NULL, NULL, 'ALWAYS', 'FORWARD,RTO')) AS v(CODE, SEQ, CALC, RATE, FIXED, MN, MX, BASE, BC, TF, TT, AP, DIRS);
